import torch

from miles.rollout.filter_hub.base_types import DynamicFilterOutput
from miles.utils.types import Sample

__all__ = ["check_reward_nonzero_std", "check_reward_mixed_group", "check_no_aborted"]


def check_reward_nonzero_std(args, samples: list[Sample], **kwargs):
    rewards = [sample.get_reward_value(args) for sample in samples]
    keep = torch.tensor(rewards, dtype=torch.float64).std() > 1e-8
    return DynamicFilterOutput(
        keep=keep,
        reason=None if keep else f"zero_std_{round(rewards[0], 1)}",
    )


def check_reward_mixed_group(args, samples: list[Sample], **kwargs):
    rewards = [sample.get_reward_value(args) for sample in samples]
    rewards_tensor = torch.tensor(rewards, dtype=torch.float)
    keep = rewards_tensor.std() > 0.0
    if keep:
        return DynamicFilterOutput(keep=True)

    reward_mean = rewards_tensor.mean().item()
    if reward_mean < 0.01:
        reason = "solve_none"
    elif reward_mean > 0.99:
        reason = "solve_all"
    else:
        reason = f"zero_std_{round(reward_mean, 3)}"
    return DynamicFilterOutput(keep=False, reason=reason)


def _flatten_samples(samples):
    """Flatten samples that may contain nested lists (from --generate-multi-samples)."""
    for s in samples:
        if isinstance(s, list):
            yield from s
        else:
            yield s


def check_no_aborted(args, samples: list[Sample], **kwargs):
    """Reject entire group if any sample was aborted (e.g. env timeout, Docker crash)."""
    if any(s.status == Sample.Status.ABORTED for s in _flatten_samples(samples)):
        return DynamicFilterOutput(keep=False, reason="group_has_aborted")
    return DynamicFilterOutput(keep=True)
